import { test, expect } from '@playwright/test';

test.describe('Inline Editing on Table Row', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should enable inline editing on table row and update data without modal', async ({ page }) => {
    // Verify initial table state
    const rows = page.locator('[data-testid="table-row"]');
    await expect(rows).toHaveCount(5);

    // Verify initial data
    const firstRow = page.locator('[data-testid="table-row-1"]');
    await expect(firstRow).toContainText('John Doe');
    await expect(firstRow).toContainText('john@example.com');

    // Click on the first row to enable inline editing
    await firstRow.click();

    // Verify editable state
    const nameInput = page.getByLabel('Name');
    await expect(nameInput).toBeVisible();
    await expect(nameInput).toHaveValue('John Doe');

    const emailInput = page.getByLabel('Email');
    await expect(emailInput).toBeVisible();
    await expect(emailInput).toHaveValue('john@example.com');

    // Update name
    await nameInput.fill('Jane Doe');
    await expect(nameInput).toHaveValue('Jane Doe');

    // Update email
    await emailInput.fill('jane.doe@example.com');
    await expect(emailInput).toHaveValue('jane.doe@example.com');

    // Verify changes are reflected
    await expect(firstRow).toContainText('Jane Doe');
    await expect(firstRow).toContainText('jane.doe@example.com');

    // Verify save button is enabled
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();

    // Click save button
    await saveButton.click();

    // Verify success message
    const successMessage = page.getByText('Row updated successfully');
    await expect(successMessage).toBeVisible();

    // Verify table is still visible
    await expect(rows).toHaveCount(5);
  });

  test('should handle empty row and prevent editing', async ({ page }) => {
    // Verify initial table state
    const rows = page.locator('[data-testid="table-row"]');
    await expect(rows).toHaveCount(5);

    // Click on the first row to enable inline editing
    const firstRow = page.locator('[data-testid="table-row-1"]');
    await firstRow.click();

    // Verify editable state
    const nameInput = page.getByLabel('Name');
    await expect(nameInput).toBeVisible();

    // Attempt to edit empty row
    await nameInput.fill('');

    // Verify editable state is still visible
    await expect(nameInput).toBeVisible();

    // Verify save button is disabled
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText('Cannot edit empty row');
    await expect(errorMessage).toBeVisible();

    // Verify table is still visible
    await expect(rows).toHaveCount(5);
  });
});
